  1: import java.io.IOException;
  2: import java.io.PrintStream;
  3: import java.nio.file.Files;
  4: import java.nio.file.Path;
  5: import java.util.ArrayList;
  6: import java.util.List;
  7: import javax.xml.XMLConstants;
  8: import javax.xml.parsers.DocumentBuilderFactory;
  9: import org.w3c.dom.Element;
 10: import org.w3c.dom.Node;
 11: import org.xml.sax.SAXException;
 12: import org.xml.sax.SAXParseException;
 13: import org.xml.sax.helpers.DefaultHandler;
 14: 
 15: /** Mandatory validation evidence, checked separately from documentary exports. Java 25, no dependencies. */
 16: public class VerifyTestReports {
 17:     public static void main(String[] args) {
 18:         System.exit(run(args, System.out, System.err));
 19:     }
 20: 
 21:     static int run(String[] args, PrintStream out, PrintStream err) {
 22:         try {
 23:             require(args.length == 1 || args.length == 3,
 24:                     "Usage: java ci/VerifyTestReports.java standard|integration [--root directory]");
 25:             String mode = args[0];
 26:             require(mode.equals("standard") || mode.equals("integration"), "Unknown validation mode.");
 27:             require(args.length == 1 || args[1].equals("--root"), "Expected --root directory.");
 28:             Path root = args.length == 3 ? Path.of(args[2]) : Path.of(".");
 29:             Counts standard = reports(root.resolve("target/surefire-reports"), "Surefire");
 30:             Counts integration = null;
 31:             if (mode.equals("integration")) {
 32:                 Path directory = root.resolve("target/failsafe-reports");
 33:                 integration = reports(directory, "Failsafe");
 34:                 summary(directory.resolve("failsafe-summary.xml"), integration);
 35:             }
 36:             out.println("Surefire: " + standard);
 37:             if (integration != null) {
 38:                 out.println("Failsafe: " + integration + "; summary verified");
 39:             }
 40:             out.println("Required test reports: PASS mode=" + mode);
 41:             return 0;
 42:         } catch (InvalidEvidence e) {
 43:             err.println("Required test reports: FAIL: " + e.getMessage());
 44:             return 1;
 45:         } catch (Exception e) {
 46:             // Do not echo parser, filesystem or report content: reports can contain sensitive data.
 47:             err.println("Required test reports: FAIL: Validation could not read the required evidence.");
 48:             return 1;
 49:         }
 50:     }
 51: 
 52:     private static Counts reports(Path directory, String family) throws Exception {
 53:         require(Files.isDirectory(directory), family + " report directory is missing.");
 54:         List<Path> files;
 55:         try (var entries = Files.list(directory)) {
 56:             files = entries.filter(path -> path.getFileName().toString().startsWith("TEST-")
 57:                             && path.getFileName().toString().endsWith(".xml"))
 58:                     .sorted().toList();
 59:         }
 60:         require(!files.isEmpty(), family + " TEST-*.xml reports are missing.");
 61:         Counts total = new Counts(0, 0, 0, 0);
 62:         for (int index = 0; index < files.size(); index++) {
 63:             String label = family + " report #" + (index + 1);
 64:             Element suite = xml(files.get(index), label);
 65:             require(suite.getTagName().equals("testsuite"), label + " is not a testsuite.");
 66:             Counts declared = new Counts(attribute(suite, "tests", label), attribute(suite, "failures", label),
 67:                     attribute(suite, "errors", label), attribute(suite, "skipped", label));
 68:             List<Element> cases = children(suite, "testcase");
 69:             long failures = 0;
 70:             long errors = 0;
 71:             long skipped = 0;
 72:             for (Element test : cases) {
 73:                 int testFailures = children(test, "failure").size();
 74:                 int testErrors = children(test, "error").size();
 75:                 int testSkipped = children(test, "skipped").size();
 76:                 require(testFailures + testErrors + testSkipped <= 1,
 77:                         label + " contains an inconsistent testcase outcome.");
 78:                 failures += testFailures;
 79:                 errors += testErrors;
 80:                 skipped += testSkipped;
 81:             }
 82:             Counts observed = new Counts(cases.size(), failures, errors, skipped);
 83:             require(declared.equals(observed), label + " counters do not match its testcases.");
 84:             require(declared.failures == 0 && declared.errors == 0, label + " records failed tests.");
 85:             total = total.plus(declared);
 86:         }
 87:         require(total.tests - total.skipped > 0, family + " executed no tests (empty or entirely skipped).");
 88:         return total;
 89:     }
 90: 
 91:     private static void summary(Path file, Counts actual) throws Exception {
 92:         String label = "Failsafe summary";
 93:         Element summary = xml(file, label);
 94:         require(summary.getTagName().equals("failsafe-summary"), label + " has an invalid root.");
 95:         String result = summary.getAttribute("result");
 96:         // Surefire writes the literal "null" when there is no failure exit code.
 97:         require(result.equals("null") || result.equals("0"), label + " does not report success.");
 98:         require(summary.getAttribute("timeout").equals("false"), label + " timed out or lacks timeout status.");
 99:         Counts declared = new Counts(childNumber(summary, "completed", label),
100:                 childNumber(summary, "failures", label), childNumber(summary, "errors", label),
101:                 childNumber(summary, "skipped", label));
102:         require(declared.equals(actual), label + " counters do not match the Failsafe test reports.");
103:         for (Element failureMessage : children(summary, "failureMessage")) {
104:             require(failureMessage.getTextContent().isBlank(), label + " contains a failure message.");
105:         }
106:     }
107: 
108:     private static Element xml(Path file, String label) throws Exception {
109:         require(Files.isRegularFile(file) && Files.size(file) > 0, label + " is missing or empty.");
110:         DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
111:         factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
112:         factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
113:         factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
114:         factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
115:         factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
116:         factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
117:         factory.setXIncludeAware(false);
118:         factory.setExpandEntityReferences(false);
119:         var builder = factory.newDocumentBuilder();
120:         builder.setErrorHandler(new DefaultHandler() {
121:             @Override public void error(SAXParseException e) throws SAXException { throw e; }
122:             @Override public void fatalError(SAXParseException e) throws SAXException { throw e; }
123:         });
124:         try (var input = Files.newInputStream(file)) {
125:             return builder.parse(input).getDocumentElement();
126:         } catch (SAXException | IOException e) {
127:             throw new InvalidEvidence(label + " is unreadable or invalid XML.");
128:         }
129:     }
130: 
131:     private static long attribute(Element element, String name, String label) throws InvalidEvidence {
132:         return number(element.getAttribute(name), label);
133:     }
134: 
135:     private static long childNumber(Element element, String name, String label) throws InvalidEvidence {
136:         List<Element> matching = children(element, name);
137:         require(matching.size() == 1, label + " is missing a counter or contains duplicate counters.");
138:         return number(matching.getFirst().getTextContent().trim(), label);
139:     }
140: 
141:     private static long number(String value, String label) throws InvalidEvidence {
142:         require(value.matches("[0-9]+"), label + " contains a missing or invalid counter.");
143:         try {
144:             return Long.parseLong(value);
145:         } catch (NumberFormatException e) {
146:             throw new InvalidEvidence(label + " contains an out-of-range counter.");
147:         }
148:     }
149: 
150:     private static List<Element> children(Element parent, String name) {
151:         List<Element> result = new ArrayList<>();
152:         for (Node node = parent.getFirstChild(); node != null; node = node.getNextSibling()) {
153:             if (node instanceof Element element && element.getTagName().equals(name)) {
154:                 result.add(element);
155:             }
156:         }
157:         return result;
158:     }
159: 
160:     private static void require(boolean condition, String message) throws InvalidEvidence {
161:         if (!condition) {
162:             throw new InvalidEvidence(message);
163:         }
164:     }
165: 
166:     private record Counts(long tests, long failures, long errors, long skipped) {
167:         Counts plus(Counts other) {
168:             return new Counts(Math.addExact(tests, other.tests), Math.addExact(failures, other.failures),
169:                     Math.addExact(errors, other.errors), Math.addExact(skipped, other.skipped));
170:         }
171: 
172:         @Override public String toString() {
173:             return "tests=" + tests + ", executed=" + (tests - skipped) + ", failures=" + failures
174:                     + ", errors=" + errors + ", skipped=" + skipped;
175:         }
176:     }
177: 
178:     private static final class InvalidEvidence extends Exception {
179:         InvalidEvidence(String message) { super(message); }
180:     }
181: }
